INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Perform standard summation.', 'Return a + b.', 'class Solution {\n    public int sum(int num1, int num2) {\n        return num1 + num2;\n    }\n}', 'Time: O(1), Space: O(1)', 'Basic syntax' FROM problems WHERE leetcode_number = 2235 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Apply temperature conversion formulas.', 'Convert Celsius to Kelvin and Fahrenheit.', 'class Solution {\n    public double[] convertTemperature(double celsius) {\n        return new double[]{celsius + 273.15, celsius * 1.80 + 32.00};\n    }\n}', 'Time: O(1), Space: O(1)', 'Float syntax' FROM problems WHERE leetcode_number = 2469 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Standard search in sorted array.', 'Maintain pointers low and high, check middle element.', 'class Solution {\n    public int search(int[] nums, int target) {\n        int l = 0, r = nums.length - 1;\n        while(l <= r){\n            int m = l + (r - l)/2;\n            if(nums[m] == target) return m;\n            if(nums[m] < target) l = m + 1;\n            else r = m - 1;\n        }\n        return -1;\n    }\n}', 'Time: O(log N), Space: O(1)', 'Binary search bounds' FROM problems WHERE leetcode_number = 704 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Binary search looking for boundary.', 'Find first index where isBadVersion(index) is true.', 'public class Solution extends VersionControl {\n    public int firstBadVersion(int n) {\n        int l = 1, r = n;\n        while(l < r) {\n            int m = l + (r - l)/2;\n            if(isBadVersion(m)) r = m;\n            else l = m + 1;\n        }\n        return l;\n    }\n}', 'Time: O(log N), Space: O(1)', 'Correct rounding bounds' FROM problems WHERE leetcode_number = 278 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Double size array.', 'Copy nums items twice into a new array.', 'class Solution {\n    public int[] getConcatenation(int[] nums) {\n        int n = nums.length;\n        int[] ans = new int[2*n];\n        for(int i=0; i<n; i++){\n            ans[i] = nums[i];\n            ans[i+n] = nums[i];\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(N)', 'Array indexing' FROM problems WHERE leetcode_number = 1929 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Cumulative additions.', 'Replace index i with sum from 0 to i.', 'class Solution {\n    public int[] runningSum(int[] nums) {\n        for(int i=1; i<nums.length; i++){\n            nums[i] += nums[i-1];\n        }\n        return nums;\n    }\n}', 'Time: O(N), Space: O(1)', 'In-place scans' FROM problems WHERE leetcode_number = 1480 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Compare frequencies.', 'Count smaller items than current.', 'class Solution {\n    public int[] smallerNumbersThanCurrent(int[] nums) {\n        int[] count = new int[101];\n        for(int num : nums) count[num]++;\n        for(int i=1; i<=100; i++) count[i] += count[i-1];\n        int[] ans = new int[nums.length];\n        for(int i=0; i<nums.length; i++){\n            ans[i] = nums[i] == 0 ? 0 : count[nums[i]-1];\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(1) external', 'Bucket sorting' FROM problems WHERE leetcode_number = 1365 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Single pass max difference.', 'Record lowest price seen, calculate current profit.', 'class Solution {\n    public int maxProfit(int[] prices) {\n        int min = Integer.MAX_VALUE, max = 0;\n        for(int p : prices){\n            if(p < min) min = p;\n            else max = Math.max(max, p - min);\n        }\n        return max;\n    }\n}', 'Time: O(N), Space: O(1)', 'Min tracking bounds' FROM problems WHERE leetcode_number = 121 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Scan diagonals of 2D matrix.', 'Calculate indices matching i==j or i+j == n-1.', 'class Solution {\n    public int diagonalSum(int[][] mat) {\n        int sum = 0, n = mat.length;\n        for(int i=0; i<n; i++){\n            sum += mat[i][i];\n            if(i != n - 1 - i) sum += mat[i][n - 1 - i];\n        }\n        return sum;\n    }\n}', 'Time: O(N), Space: O(1)', 'Matrix coordinates' FROM problems WHERE leetcode_number = 1572 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Check left sum vs right sum.', 'Find index where sum(0..i-1) == sum(i+1..end).', 'class Solution {\n    public int pivotIndex(int[] nums) {\n        int sum = 0, left = 0;\n        for(int x : nums) sum += x;\n        for(int i=0; i<nums.length; i++){\n            if(left == sum - left - nums[i]) return i;\n            left += nums[i];\n        }\n        return -1;\n    }\n}', 'Time: O(N), Space: O(1)', 'Running sums comparison' FROM problems WHERE leetcode_number = 724 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Precalculate sums.', 'Cache cumulative range totals.', 'class NumArray {\n    int[] sums;\n    public NumArray(int[] nums) {\n        sums = new int[nums.length + 1];\n        for(int i=0; i<nums.length; i++) sums[i+1] = sums[i] + nums[i];\n    }\n    public int sumRange(int left, int right) {\n        return sums[right+1] - sums[left];\n    }\n}', 'Time: O(1) query, Space: O(N)', 'Prefix array size padding' FROM problems WHERE leetcode_number = 303 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'In-place element removal.', 'Iterate and swap non-target elements to the front.', 'class Solution {\n    public int removeElement(int[] nums, int val) {\n        int k = 0;\n        for(int x : nums){\n            if(x != val) nums[k++] = x;\n        }\n        return k;\n    }\n}', 'Time: O(N), Space: O(1)', 'Array rewriting index pointers' FROM problems WHERE leetcode_number = 27 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Pointer tracking.', 'Rewrite distinct items sequentially.', 'class Solution {\n    public int removeDuplicates(int[] nums) {\n        int k = 1;\n        for(int i=1; i<nums.length; i++){\n            if(nums[i] != nums[i-1]) nums[k++] = nums[i];\n        }\n        return k;\n    }\n}', 'Time: O(N), Space: O(1)', 'Boundary checks' FROM problems WHERE leetcode_number = 26 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Boundary shrinking.', 'Traverse spiral boundaries top-to-bottom, left-to-right.', 'class Solution {\n    public List<Integer> spiralOrder(int[][] matrix) {\n        List<Integer> ans = new ArrayList<>();\n        int r1 = 0, r2 = matrix.length - 1, c1 = 0, c2 = matrix[0].length - 1;\n        while(r1 <= r2 && c1 <= c2){\n            for(int c=c1; c<=c2; c++) ans.add(matrix[r1][c]);\n            for(int r=r1+1; r<=r2; r++) ans.add(matrix[r][c2]);\n            if(r1 < r2 && c1 < c2){\n                for(int c=c2-1; c>c1; c--) ans.add(matrix[r2][c]);\n                for(int r=r2; r>r1; r--) ans.add(matrix[r][c1]);\n            }\n            r1++; r2--; c1++; c2--;\n        }\n        return ans;\n    }\n}', 'Time: O(N*M), Space: O(1)', 'Boundary shrinkage checks' FROM problems WHERE leetcode_number = 54 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Transpose then reverse.', 'Swap matrix[i][j] with matrix[j][i], then reverse rows.', 'class Solution {\n    public void rotate(int[][] matrix) {\n        int n = matrix.length;\n        for(int i=0; i<n; i++){\n            for(int j=i+1; j<n; j++){\n                int temp = matrix[i][j];\n                matrix[i][j] = matrix[j][i];\n                matrix[j][i] = temp;\n            }\n        }\n        for(int i=0; i<n; i++){\n            for(int j=0; j<n/2; j++){\n                int temp = matrix[i][j];\n                matrix[i][j] = matrix[i][n - 1 - j];\n                matrix[i][n - 1 - j] = temp;\n            }\n        }\n    }\n}', 'Time: O(N^2), Space: O(1)', 'Row reversing indexing' FROM problems WHERE leetcode_number = 48 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Reverse subarrays.', 'Reverse whole array, reverse first k, reverse remaining.', 'class Solution {\n    public void rotate(int[] nums, int k) {\n        k %= nums.length;\n        reverse(nums, 0, nums.length - 1);\n        reverse(nums, 0, k - 1);\n        reverse(nums, k, nums.length - 1);\n    }\n    private void reverse(int[] nums, int start, int end){\n        while(start < end){\n            int temp = nums[start];\n            nums[start++] = nums[end];\n            nums[end--] = temp;\n        }\n    }\n}', 'Time: O(N), Space: O(1)', 'Modular k checks' FROM problems WHERE leetcode_number = 189 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Two pointer swapping.', 'Swap evens to front, odds to back.', 'class Solution {\n    public int[] sortArrayByParity(int[] nums) {\n        int l = 0, r = nums.length - 1;\n        while(l < r){\n            if(nums[l] % 2 > nums[r] % 2){\n                int temp = nums[l];\n                nums[l] = nums[r];\n                nums[r] = temp;\n            }\n            if(nums[l] % 2 == 0) l++;\n            if(nums[r] % 2 != 0) r--;\n        }\n        return nums;\n    }\n}', 'Time: O(N), Space: O(1)', 'Conditional swapping checks' FROM problems WHERE leetcode_number = 905 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'First unique occurrence.', 'Store frequencies, find first with frequency == 1.', 'class Solution {\n    public int firstUniqChar(String s) {\n        int[] count = new int[26];\n        for(char c : s.toCharArray()) count[c - ''a'']++;\n        for(int i=0; i<s.length(); i++){\n            if(count[s.charAt(i) - ''a''] == 1) return i;\n        }\n        return -1;\n    }\n}', 'Time: O(N), Space: O(1)', 'Alphabet mapping offsets' FROM problems WHERE leetcode_number = 387 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Left and right pointers.', 'Compare valid alphanumeric chars moving inwards.', 'class Solution {\n    public boolean isPalindrome(String s) {\n        int l = 0, r = s.length() - 1;\n        while(l < r){\n            if(!Character.isLetterOrDigit(s.charAt(l))) l++;\n            else if(!Character.isLetterOrDigit(s.charAt(r))) r--;\n            else {\n                if(Character.toLowerCase(s.charAt(l)) != Character.toLowerCase(s.charAt(r))) return false;\n                l++; r--;\n            }\n        }\n        return true;\n    }\n}', 'Time: O(N), Space: O(1)', 'Non-alphanumeric checks' FROM problems WHERE leetcode_number = 125 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Find position or insert index.', 'Standard binary search. Low pointer lands on target insert position if not found.', 'class Solution {\n    public int searchInsert(int[] nums, int target) {\n        int l = 0, r = nums.length - 1;\n        while(l <= r){\n            int m = l + (r - l)/2;\n            if(nums[m] == target) return m;\n            if(nums[m] < target) l = m + 1;\n            else r = m - 1;\n        }\n        return l;\n    }\n}', 'Time: O(log N), Space: O(1)', 'Loop exit condition checks' FROM problems WHERE leetcode_number = 35 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Double binary search.', 'Find first index and last index of target elements.', 'class Solution {\n    public int[] searchRange(int[] nums, int target) {\n        int[] ans = {-1, -1};\n        ans[0] = findBound(nums, target, true);\n        ans[1] = findBound(nums, target, false);\n        return ans;\n    }\n    private int findBound(int[] nums, int target, boolean isFirst){\n        int l = 0, r = nums.length - 1, idx = -1;\n        while(l <= r){\n            int m = l + (r - l)/2;\n            if(nums[m] == target){\n                idx = m;\n                if(isFirst) r = m - 1;\n                else l = m + 1;\n            } else if(nums[m] < target) l = m + 1;\n            else r = m - 1;\n        }\n        return idx;\n    }\n}', 'Time: O(log N), Space: O(1)', 'Boundary checks' FROM problems WHERE leetcode_number = 34 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Frequency map matching.', 'Record frequencies, compare matching arrays.', 'class Solution {\n    public boolean isAnagram(String s, String t) {\n        if(s.length() != t.length()) return false;\n        int[] count = new int[26];\n        for(int i=0; i<s.length(); i++){\n            count[s.charAt(i) - ''a'']++;\n            count[t.charAt(i) - ''a'']--;\n        }\n        for(int val : count) if(val != 0) return false;\n        return true;\n    }\n}', 'Time: O(N), Space: O(1)', 'Length checking edge cases' FROM problems WHERE leetcode_number = 242 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Complement dictionary mapping.', 'Find value (target - current) in HashMap.', 'class Solution {\n    public int[] twoSum(int[] nums, int target) {\n        Map<Integer, Integer> map = new HashMap<>();\n        for(int i=0; i<nums.length; i++){\n            int comp = target - nums[i];\n            if(map.containsKey(comp)) return new int[]{map.get(comp), i};\n            map.put(nums[i], i);\n        }\n        return new int[0];\n    }\n}', 'Time: O(N), Space: O(N)', 'Returning correct indices' FROM problems WHERE leetcode_number = 1 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Pointers from edges.', 'Adjust pointers depending on current sum vs target.', 'class Solution {\n    public int[] twoSum(int[] numbers, int target) {\n        int l = 0, r = numbers.length - 1;\n        while(l < r){\n            int sum = numbers[l] + numbers[r];\n            if(sum == target) return new int[]{l + 1, r + 1};\n            if(sum < target) l++;\n            else r--;\n        }\n        return new int[0];\n    }\n}', 'Time: O(N), Space: O(1)', '1-based index returns' FROM problems WHERE leetcode_number = 167 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Maximize volume.', 'Compute volume between left and right height boundaries, move smaller height inwards.', 'class Solution {\n    public int maxArea(int[] height) {\n        int l = 0, r = height.length - 1, max = 0;\n        while(l < r){\n            max = Math.max(max, Math.min(height[l], height[r]) * (r - l));\n            if(height[l] < height[r]) l++;\n            else r--;\n        }\n        return max;\n    }\n}', 'Time: O(N), Space: O(1)', 'Pointer moving decisions' FROM problems WHERE leetcode_number = 11 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Sum first K, slide remaining.', 'Add right, subtract left element from sum.', 'class Solution {\n    public double findMaxAverage(int[] nums, int k) {\n        double sum = 0;\n        for(int i=0; i<k; i++) sum += nums[i];\n        double max = sum;\n        for(int i=k; i<nums.length; i++){\n            sum += nums[i] - nums[i - k];\n            max = Math.max(max, sum);\n        }\n        return max / k;\n    }\n}', 'Time: O(N), Space: O(1)', 'Floating division' FROM problems WHERE leetcode_number = 643 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Slide frequency matching.', 'Sliding frequency counts matching anagram source pattern.', 'class Solution {\n    public List<Integer> findAnagrams(String s, String p) {\n        List<Integer> ans = new ArrayList<>();\n        if(s.length() < p.length()) return ans;\n        int[] pCount = new int[26], sCount = new int[26];\n        for(int i=0; i<p.length(); i++){\n            pCount[p.charAt(i) - ''a'']++;\n            sCount[s.charAt(i) - ''a'']++;\n        }\n        if(Arrays.equals(pCount, sCount)) ans.add(0);\n        for(int i=p.length(); i<s.length(); i++){\n            sCount[s.charAt(i) - ''a'']++;\n            sCount[s.charAt(i - p.length()) - ''a'']--;\n            if(Arrays.equals(pCount, sCount)) ans.add(i - p.length() + 1);\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(1)', 'Array comparisons' FROM problems WHERE leetcode_number = 438 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Push openers, match closers.', 'Check top of stack matches matching closed brackets.', 'class Solution {\n    public boolean isValid(String s) {\n        Stack<Character> st = new Stack<>();\n        for(char c : s.toCharArray()){\n            if(c == ''('') st.push('')'');\n            else if(c == ''{'') st.push(''}'');\n            else if(c == ''['') st.push('']'');\n            else if(st.isEmpty() || st.pop() != c) return false;\n        }\n        return st.isEmpty();\n    }\n}', 'Time: O(N), Space: O(N)', 'Empty stack checking' FROM problems WHERE leetcode_number = 20 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Secondary minimum tracking.', 'Maintain secondary minimum history stack alongside main value stack.', 'class MinStack {\n    private Stack<Integer> s = new Stack<>(), min = new Stack<>();\n    public void push(int val) {\n        s.push(val);\n        if(min.isEmpty() || val <= min.peek()) min.push(val);\n    }\n    public void pop() {\n        if(s.pop().equals(min.peek())) min.pop();\n    }\n    public int top() { return s.peek(); }\n    public int getMin() { return min.peek(); }\n}', 'Time: O(1), Space: O(N)', 'Push equivalence comparisons' FROM problems WHERE leetcode_number = 155 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Loop level arrays.', 'Retrieve size of queue, loop to drain level, enqueue children.', 'class Solution {\n    public List<List<Integer>> levelOrder(TreeNode root) {\n        List<List<Integer>> ans = new ArrayList<>();\n        if(root == null) return ans;\n        Queue<TreeNode> q = new LinkedList<>();\n        q.add(root);\n        while(!q.isEmpty()){\n            int sz = q.size();\n            List<Integer> level = new ArrayList<>();\n            for(int i=0; i<sz; i++){\n                TreeNode curr = q.poll();\n                level.add(curr.val);\n                if(curr.left != null) q.add(curr.left);\n                if(curr.right != null) q.add(curr.right);\n            }\n            ans.add(level);\n        }\n        return ans;\n    }\n}', 'Time: O(N), Space: O(N)', 'Null checks' FROM problems WHERE leetcode_number = 102 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'BFS source queueing.', 'Initialize queue with all rotting locations, diffuse neighbors level by level.', 'class Solution {\n    public int orangesRotting(int[][] grid) {\n        Queue<int[]> q = new LinkedList<>();\n        int fresh = 0, time = 0;\n        for(int r=0; r<grid.length; r++){\n            for(int c=0; c<grid[0].length; c++){\n                if(grid[r][c] == 2) q.add(new int[]{r, c});\n                else if(grid[r][c] == 1) fresh++;\n            }\n        }\n        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};\n        while(!q.isEmpty() && fresh > 0){\n            int sz = q.size();\n            for(int i=0; i<sz; i++){\n                int[] curr = q.poll();\n                for(int[] d : dirs){\n                    int nr = curr[0] + d[0], nc = curr[1] + d[1];\n                    if(nr>=0 && nr<grid.length && nc>=0 && nc<grid[0].length && grid[nr][nc] == 1){\n                        grid[nr][nc] = 2;\n                        q.add(new int[]{nr, nc});\n                        fresh--;\n                    }\n                }\n            }\n            time++;\n        }\n        return fresh == 0 ? time : -1;\n    }\n}', 'Time: O(R*C), Space: O(R*C)', 'Empty checks' FROM problems WHERE leetcode_number = 994 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Adjust node link chains.', 'Iterate node references, reversing pointer directions.', 'class Solution {\n    public ListNode reverseList(ListNode head) {\n        ListNode prev = null, curr = head;\n        while(curr != null){\n            ListNode next = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = next;\n        }\n        return prev;\n    }\n}', 'Time: O(N), Space: O(1)', 'Pointer preservation checks' FROM problems WHERE leetcode_number = 206 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Target boundaries reversal.', 'Navigate to index boundaries, reverse segment range and connect links.', 'class Solution {\n    public ListNode reverseBetween(ListNode head, int left, int right) {\n        if(head == null) return null;\n        ListNode dummy = new ListNode(0); dummy.next = head;\n        ListNode pre = dummy;\n        for(int i=0; i<left-1; i++) pre = pre.next;\n        ListNode start = pre.next, then = start.next;\n        for(int i=0; i<right-left; i++){\n            start.next = then.next;\n            then.next = pre.next;\n            pre.next = then;\n            then = start.next;\n        }\n        return dummy.next;\n    }\n}', 'Time: O(N), Space: O(1)', 'Dummy node creations' FROM problems WHERE leetcode_number = 92 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Boyre-Moore voting algorithm.', 'Track candidate value and increments/decrements votes.', 'class Solution {\n    public int majorityElement(int[] nums) {\n        int cand = nums[0], count = 0;\n        for(int x : nums){\n            if(count == 0) cand = x;\n            count += (x == cand) ? 1 : -1;\n        }\n        return cand;\n    }\n}', 'Time: O(N), Space: O(1)', 'Tie breaks' FROM problems WHERE leetcode_number = 169 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Kadanes algorithm.', 'Maintain running sum, reset to 0 if sum drops below 0.', 'class Solution {\n    public int maxSubArray(int[] nums) {\n        int max = nums[0], sum = 0;\n        for(int x : nums){\n            sum += x;\n            max = Math.max(max, sum);\n            if(sum < 0) sum = 0;\n        }\n        return max;\n    }\n}', 'Time: O(N), Space: O(1)', 'Negative limits' FROM problems WHERE leetcode_number = 53 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Tree max path traversal.', 'Calculate max(left, right) + 1 recursively.', 'class Solution {\n    public int maxDepth(TreeNode root) {\n        if(root == null) return 0;\n        return Math.max(maxDepth(root.left), maxDepth(root.right)) + 1;\n    }\n}', 'Time: O(N), Space: O(H)', 'Base node null conditions' FROM problems WHERE leetcode_number = 104 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'TreeNode swaps.', 'Swap left and right children recursively.', 'class Solution {\n    public TreeNode invertTree(TreeNode root) {\n        if(root == null) return null;\n        TreeNode temp = root.left;\n        root.left = invertTree(root.right);\n        root.right = invertTree(temp);\n        return root;\n    }\n}', 'Time: O(N), Space: O(H)', 'Node checks' FROM problems WHERE leetcode_number = 226 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'BST binary directions search.', 'Go left if target < val, else go right.', 'class Solution {\n    public TreeNode searchBST(TreeNode root, int val) {\n        if(root == null || root.val == val) return root;\n        return val < root.val ? searchBST(root.left, val) : searchBST(root.right, val);\n    }\n}', 'Time: O(H), Space: O(H)', 'Null conditions' FROM problems WHERE leetcode_number = 700 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Recursive leaf insertion.', 'Insert into left or right subtree recursively, return root.', 'class Solution {\n    public TreeNode insertIntoBST(TreeNode root, int val) {\n        if(root == null) return new TreeNode(val);\n        if(val < root.val) root.left = insertIntoBST(root.left, val);\n        else root.right = insertIntoBST(root.right, val);\n        return root;\n    }\n}', 'Time: O(H), Space: O(H)', 'BST conditions' FROM problems WHERE leetcode_number = 701 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Min-heap filtering.', 'Add elements to min-heap. Evict elements when size > K.', 'class Solution {\n    public int findKthLargest(int[] nums, int k) {\n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for(int x : nums){\n            pq.add(x);\n            if(pq.size() > k) pq.poll();\n        }\n        return pq.peek();\n    }\n}', 'Time: O(N log K), Space: O(K)', 'Heap direction checks' FROM problems WHERE leetcode_number = 215 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Bucketing frequencies.', 'Store frequencies, bucket elements by frequency, fetch top K.', 'class Solution {\n    public int[] topKFrequent(int[] nums, int k) {\n        Map<Integer, Integer> map = new HashMap<>();\n        for(int x : nums) map.put(x, map.getOrDefault(x, 0) + 1);\n        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> map.get(a) - map.get(b));\n        for(int key : map.keySet()){\n            pq.add(key);\n            if(pq.size() > k) pq.poll();\n        }\n        int[] ans = new int[k];\n        for(int i=0; i<k; i++) ans[i] = pq.poll();\n        return ans;\n    }\n}', 'Time: O(N log K), Space: O(N)', 'Hash indexing' FROM problems WHERE leetcode_number = 347 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Build list combinations.', 'Recursively include and exclude elements in decision branch.', 'class Solution {\n    public List<List<Integer>> subsets(int[] nums) {\n        List<List<Integer>> ans = new ArrayList<>();\n        backtrack(ans, new ArrayList<>(), nums, 0);\n        return ans;\n    }\n    private void backtrack(List<List<Integer>> ans, List<Integer> temp, int[] nums, int start){\n        ans.add(new ArrayList<>(temp));\n        for(int i=start; i<nums.length; i++){\n            temp.add(nums[i]);\n            backtrack(ans, temp, nums, i+1);\n            temp.remove(temp.size()-1);\n        }\n    }\n}', 'Time: O(2^N), Space: O(N)', 'Duplicate branch allocations' FROM problems WHERE leetcode_number = 78 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Build permutation mappings.', 'Generate recursive permutations swapping positions or tracking visited.', 'class Solution {\n    public List<List<Integer>> permute(int[] nums) {\n        List<List<Integer>> ans = new ArrayList<>();\n        backtrack(ans, new ArrayList<>(), nums);\n        return ans;\n    }\n    private void backtrack(List<List<Integer>> ans, List<Integer> temp, int[] nums){\n        if(temp.size() == nums.length) ans.add(new ArrayList<>(temp));\n        else {\n            for(int i=0; i<nums.length; i++){\n                if(temp.contains(nums[i])) continue;\n                temp.add(nums[i]);\n                backtrack(ans, temp, nums);\n                temp.remove(temp.size()-1);\n            }\n        }\n    }\n}', 'Time: O(N * N!), Space: O(N)', 'Array contains limitations' FROM problems WHERE leetcode_number = 46 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Mark grid connected coordinates.', 'Traverse land segments recursively marking them as water.', 'class Solution {\n    public int numIslands(char[][] grid) {\n        int count = 0;\n        for(int r=0; r<grid.length; r++){\n            for(int c=0; c<grid[0].length; c++){\n                if(grid[r][c] == ''1''){\n                    count++; dfs(grid, r, c);\n                }\n            }\n        }\n        return count;\n    }\n    private void dfs(char[][] grid, int r, int c){\n        if(r<0 || r>=grid.length || c<0 || c>=grid[0].length || grid[r][c] == ''0'') return;\n        grid[r][c] = ''0'';\n        dfs(grid, r+1, c); dfs(grid, r-1, c);\n        dfs(grid, r, c+1); dfs(grid, r, c-1);\n    }\n}', 'Time: O(R*C), Space: O(R*C)', 'Bounds checking limits' FROM problems WHERE leetcode_number = 200 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'HashMap visited tracks.', 'Traverse neighbors, deep copying neighbors and tracking copies in map.', 'class Solution {\n    private Map<Node, Node> map = new HashMap<>();\n    public Node cloneGraph(Node node) {\n        if(node == null) return null;\n        if(map.containsKey(node)) return map.get(node);\n        Node clone = new Node(node.val, new ArrayList<>());\n        map.put(node, clone);\n        for(Node n : node.neighbors) clone.neighbors.add(cloneGraph(n));\n        return clone;\n    }\n}', 'Time: O(V+E), Space: O(V)', 'Visited tracking cache' FROM problems WHERE leetcode_number = 133 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, '1D DP sequence mapping.', 'DP relation matching: dp[i] = dp[i-1] + dp[i-2].', 'class Solution {\n    public int climbStairs(int n) {\n        if(n <= 2) return n;\n        int a = 1, b = 2;\n        for(int i=3; i<=n; i++){\n            int sum = a + b;\n            a = b; b = sum;\n        }\n        return b;\n    }\n}', 'Time: O(N), Space: O(1)', 'Iterative swaps bounds' FROM problems WHERE leetcode_number = 70 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Cache change totals.', 'DP bottom-up array mapping minimum coins per target amount.', 'class Solution {\n    public int coinChange(int[] coins, int amount) {\n        int[] dp = new int[amount+1];\n        Arrays.fill(dp, amount+1);\n        dp[0] = 0;\n        for(int i=1; i<=amount; i++){\n            for(int c : coins){\n                if(i - c >= 0) dp[i] = Math.min(dp[i], dp[i-c] + 1);\n            }\n        }\n        return dp[amount] > amount ? -1 : dp[amount];\n    }\n}', 'Time: O(N*C), Space: O(N)', 'Default initialization limits' FROM problems WHERE leetcode_number = 322 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'TrieNode letter arrays.', 'Define TrieNode containing TrieNode[26] array and boolean isWord flag.', 'class Trie {\n    class Node { Node[] children = new Node[26]; boolean isWord; }\n    private Node root = new Node();\n    public void insert(String word) {\n        Node curr = root;\n        for(char c : word.toCharArray()){\n            if(curr.children[c-''a''] == null) curr.children[c-''a''] = new Node();\n            curr = curr.children[c-''a''];\n        }\n        curr.isWord = true;\n    }\n    public boolean search(String word) {\n        Node curr = find(word); return curr != null && curr.isWord;\n    }\n    public boolean startsWith(String prefix) { return find(prefix) != null; }\n    private Node find(String s){\n        Node curr = root;\n        for(char c : s.toCharArray()){\n            curr = curr.children[c-''a''];\n            if(curr == null) return null;\n        }\n        return curr;\n    }\n}', 'Time: O(L), Space: O(Alphabet*L)', 'Char array index boundaries' FROM problems WHERE leetcode_number = 208 ON CONFLICT (problem_id) DO NOTHING;

INSERT INTO problem_details (problem_id, intuition, approach, code_snippet, complexity_analysis, what_i_learned)
SELECT id, 'Trie backtracking traversal.', 'Implement recursive search using wildcard dot validations.', 'class WordDictionary {\n    class Node { Node[] children = new Node[26]; boolean isWord; }\n    private Node root = new Node();\n    public void addWord(String word) {\n        Node curr = root;\n        for(char c : word.toCharArray()){\n            if(curr.children[c-''a''] == null) curr.children[c-''a''] = new Node();\n            curr = curr.children[c-''a''];\n        }\n        curr.isWord = true;\n    }\n    public boolean search(String word) { return match(word.toCharArray(), 0, root); }\n    private boolean match(char[] chs, int k, Node node){\n        if(k == chs.length) return node.isWord;\n        if(chs[k] == ''.''){\n            for(Node child : node.children) if(child != null && match(chs, k+1, child)) return true;\n            return false;\n        }\n        return node.children[chs[k]-''a''] != null && match(chs, k+1, node.children[chs[k]-''a'']);\n    }\n}', 'Time: O(L), Space: O(Alphabet*L)', 'Wildcard path matching loops' FROM problems WHERE leetcode_number = 211 ON CONFLICT (problem_id) DO NOTHING;
